import { MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, CircleGeometry, MeshBasicNodeMaterial, DoubleSide, Vector3 } = ctx.THREE;

  const root = new Group();

  // ----- BACKGROUND (optional, can be omitted if not needed) -----
  // Not creating a full stage backdrop per spec, only cards.

  // ----- TEXT CONTENT -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Expect items in groups of three: icon, title, body
  const cardCount = Math.floor(items.length / 3);
  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const gap = 0.25;
  const totalWidth = cardCount * cardWidth + (cardCount - 1) * gap; // should be 5.0 for three cards

  // Colors from visual spec
  const gradTop = '#191921';
  const gradBottom = '#121218';
  const inkColor = '#16161d';
  const paperColor = '#e8ecf2';
  const accentColor = '#ff2a38';
  const borderColor = '#26262f';

  // Store timelines and disposables for cleanup
  const timelines = [];
  const disposables = [];

  for (let i = 0; i < cardCount; i++) {
    const baseIdx = i * 3;
    const iconItem = items[baseIdx];
    const titleItem = items[baseIdx + 1];
    const bodyItem = items[baseIdx + 2];

    const cardGroup = new Group();
    cardGroup.name = `card-${i + 1}`;

    // Position cards centred
    const xPos = -totalWidth / 2 + cardWidth / 2 + i * (cardWidth + gap);
    cardGroup.position.set(xPos, 0, 0);
    root.add(cardGroup);

    // ----- CARD PLANE -----
    const planeGeom = new PlaneGeometry(cardWidth, cardHeight);
    const planeMat = new MeshStandardNodeMaterial();
    // Gradient albedo via node
    const uvNode = uv();
    const topCol = color(gradTop);
    const bottomCol = color(gradBottom);
    planeMat.colorNode = mix(topCol, bottomCol, uvNode.y);
    planeMat.roughness = 0.6;
    planeMat.metalness = 0.25;
    planeMat.clearcoat = 0.15;
    planeMat.side = DoubleSide;
    planeMat.transparent = true;
    planeMat.opacity = 0; // start invisible for stagger animation
    const planeMesh = new Mesh(planeGeom, planeMat);
    planeMesh.name = 'card-plane';
    // Enable raycast on plane for hover
    planeMesh.userData = { handlers: {} };
    cardGroup.add(planeMesh);
    disposables.push(planeMat, planeGeom, planeMesh);

    // ----- CONTACT SHADOW -----
    const shadowGeom = new CircleGeometry(cardWidth * 0.6, 32);
    const shadowMat = new MeshBasicNodeMaterial({ color: 0x000000, transparent: true, opacity: 0.5 });
    const shadowMesh = new Mesh(shadowGeom, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = -cardHeight / 2 - 0.01;
    shadowMesh.scale.setScalar(1);
    cardGroup.add(shadowMesh);
    disposables.push(shadowGeom, shadowMat, shadowMesh);

    // ----- ICON DISC -----
    const discDiameter = 0.4;
    const discRadius = discDiameter / 2;
    const discDepth = 0.05;
    const discGeom = new CylinderGeometry(discRadius, discRadius, discDepth, 32);
    const discMat = new MeshStandardNodeMaterial();
    discMat.color = new Vector3().setHex(inkColor);
    discMat.roughness = 0.55;
    discMat.metalness = 0.5;
    discMat.clearcoat = 0.2;
    discMat.emissive = new Vector3().setHex(accentColor);
    discMat.emissiveIntensity = 1.6;
    discMat.side = DoubleSide;
    const discMesh = new Mesh(discGeom, discMat);
    discMesh.rotation.x = Math.PI / 2; // lay flat on card surface
    discMesh.position.y = cardHeight / 2 - 0.375 - discRadius; // below top padding
    discMesh.position.z = discDepth / 2 + 0.001; // protrude slightly
    cardGroup.add(discMesh);
    disposables.push(discGeom, discMat, discMesh);

    // ----- ICON GLYPH TEXT -----
    if (iconItem?.text) {
      const glyph = ctx.fontAtlas.createText(iconItem.text, {
        fontSize: 20,
        color: accentColor,
        align: 'center',
      });
      // Center glyph on disc
      glyph.position.set(0, discMesh.position.y, discDepth + 0.002);
      cardGroup.add(glyph);
    }

    // ----- TITLE TEXT -----
    if (titleItem?.text) {
      const title = ctx.fontAtlas.createText(titleItem.text, {
        fontSize: 20,
        color: paperColor,
        align: 'center',
        lineHeight: 1.2,
      });
      // Position under icon disc with gap 0.25
      const titleY = discMesh.position.y - discRadius - 0.25 - 0.1; // rough offset
      title.position.set(0, titleY, 0.01);
      cardGroup.add(title);
    }

    // ----- BODY TEXT -----
    if (bodyItem?.text) {
      const body = ctx.fontAtlas.createText(bodyItem.text, {
        fontSize: 13,
        color: paperColor,
        align: 'center',
        lineHeight: 1.5,
        maxWidthPx: 500,
      });
      const bodyY = discMesh.position.y - discRadius - 0.25 - 0.1 - 0.3; // further down
      body.position.set(0, bodyY, 0.01);
      cardGroup.add(body);
    }

    // ----- HOVER INTERACTION -----
    const hoverTL = gsap.timeline({ paused: true });
    hoverTL
      .to(cardGroup.position, {
        y: 0.06,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0)
      .to(cardGroup.position, {
        z: 0.12,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0)
      .to(shadowMesh.scale, {
        x: 1.3,
        y: 1.3,
        z: 1.3,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0)
      .to(shadowMat, {
        opacity: 0.35,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0)
      .to(discMat, {
        emissiveIntensity: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);

    // attach handlers to plane mesh
    const onPointerOver = () => hoverTL.play();
    const onPointerOut = () => hoverTL.reverse();

    planeMesh.userData.handlers.pointerover = onPointerOver;
    planeMesh.userData.handlers.pointerout = onPointerOut;

    timelines.push(hoverTL);
  }

  // ----- STAGGERED ENTRY ANIMATION -----
  const entryTL = gsap.timeline();
  root.children.forEach((cardGrp, idx) => {
    entryTL.fromTo(
      cardGrp.position,
      { y: 0.2 },
      { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      idx * 0.08
    );
    entryTL.fromTo(
      cardGrp.children[0].material, // plane material
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      idx * 0.08
    );
  });
  timelines.push(entryTL);

  // ----- CLEANUP -----
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(obj => {
      if (obj.dispose) obj.dispose();
    });
  };

  return root;
}
